ALTER TABLE "commercial_billing_orders" ADD COLUMN "external_invoice_number" text;--> statement-breakpoint
ALTER TABLE "commercial_billing_orders" ADD COLUMN "invoice_issued_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "commercial_billing_orders" ADD COLUMN "payment_due_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "commercial_payment_events" ADD COLUMN "confirmed_by_operator" text;--> statement-breakpoint
ALTER TABLE "commercial_payment_events" ADD COLUMN "confirmation_reason" text;--> statement-breakpoint
ALTER TABLE "commercial_payments" ADD COLUMN "bank_transaction_reference" text;--> statement-breakpoint
CREATE UNIQUE INDEX "commercial_billing_orders_invoice_number_unique" ON "commercial_billing_orders" USING btree ("organization_id",lower(btrim("external_invoice_number"))) WHERE "commercial_billing_orders"."external_invoice_number" IS NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "commercial_payments_bank_reference_unique" ON "commercial_payments" USING btree (lower(btrim("bank_transaction_reference"))) WHERE "commercial_payments"."bank_transaction_reference" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "commercial_billing_orders" ADD CONSTRAINT "commercial_billing_orders_invoice_metadata_shape" CHECK (("commercial_billing_orders"."external_invoice_number" IS NULL AND "commercial_billing_orders"."invoice_issued_at" IS NULL AND "commercial_billing_orders"."payment_due_at" IS NULL) OR ("commercial_billing_orders"."provider_code" = 'manual-bank-transfer' AND length(btrim("commercial_billing_orders"."external_invoice_number")) BETWEEN 1 AND 120 AND "commercial_billing_orders"."invoice_issued_at" IS NOT NULL AND "commercial_billing_orders"."payment_due_at" IS NOT NULL AND "commercial_billing_orders"."payment_due_at" >= "commercial_billing_orders"."invoice_issued_at"));--> statement-breakpoint
ALTER TABLE "commercial_payment_events" ADD CONSTRAINT "commercial_payment_events_confirmation_audit_shape" CHECK (("commercial_payment_events"."confirmed_by_operator" IS NULL AND "commercial_payment_events"."confirmation_reason" IS NULL) OR ("commercial_payment_events"."payment_id" IS NOT NULL AND "commercial_payment_events"."confirmed_by_operator" IS NOT NULL AND "commercial_payment_events"."confirmation_reason" IS NOT NULL AND length(btrim("commercial_payment_events"."confirmed_by_operator")) BETWEEN 1 AND 200 AND length(btrim("commercial_payment_events"."confirmation_reason")) BETWEEN 12 AND 500));--> statement-breakpoint
ALTER TABLE "commercial_payments" ADD CONSTRAINT "commercial_payments_bank_reference_nonempty" CHECK ("commercial_payments"."bank_transaction_reference" IS NULL OR length(btrim("commercial_payments"."bank_transaction_reference")) BETWEEN 1 AND 200);